function getElevation(latitude, longitude) {
  if (latitude < ELEVATION_MIN_LATITUDE || latitude > ELEVATION_MAX_LATITUDE ||
      longitude < ELEVATION_MIN_LONGITUDE || longitude > ELEVATION_MAX_LONGITUDE) {
    throw new RangeError("latitude must be -90..90 and longitude must be -180..180");
  }
  var latitudeIndex = Math.round(latitude) + 90;
  var longitudeIndex = Math.round(longitude) + 180;
  return ELEVATION_DATA[latitudeIndex * ELEVATION_LONGITUDE_SIZE + longitudeIndex];
}

// 새로 작성한 부분: 네 개의 1° 격자점을 이용한 쌍선형 보간입니다.
function getElevationInterpolated(latitude, longitude) {
  if (latitude < ELEVATION_MIN_LATITUDE || latitude > ELEVATION_MAX_LATITUDE ||
      longitude < ELEVATION_MIN_LONGITUDE || longitude > ELEVATION_MAX_LONGITUDE) {
    throw new RangeError("latitude must be -90..90 and longitude must be -180..180");
  }

  // 정수 좌표는 기존 조회 함수와 완전히 같은 값을 반환합니다.
  if (Number.isInteger(latitude) && Number.isInteger(longitude)) {
    return getElevation(latitude, longitude);
  }

  var latitudeBase = Math.floor(latitude);
  var latitudeIndex0 = latitudeBase + 90;
  var latitudeIndex1 = Math.min(latitudeIndex0 + 1, 180);
  var latitudeWeight = latitude - latitudeBase;

  // 180°는 -180°와 같은 경도입니다.
  var wrappedLongitude = longitude === 180 ? -180 : longitude;
  var longitudeBase = Math.floor(wrappedLongitude);
  var longitudeIndex0 = longitudeBase + 180;
  var longitudeIndex1 = longitudeIndex0 + 1;
  if (longitudeIndex1 >= ELEVATION_LONGITUDE_SIZE) {
    longitudeIndex1 = 0;
  }
  var longitudeWeight = wrappedLongitude - longitudeBase;

  var southWest = ELEVATION_DATA[latitudeIndex0 * ELEVATION_LONGITUDE_SIZE + longitudeIndex0];
  var southEast = ELEVATION_DATA[latitudeIndex0 * ELEVATION_LONGITUDE_SIZE + longitudeIndex1];
  var northWest = ELEVATION_DATA[latitudeIndex1 * ELEVATION_LONGITUDE_SIZE + longitudeIndex0];
  var northEast = ELEVATION_DATA[latitudeIndex1 * ELEVATION_LONGITUDE_SIZE + longitudeIndex1];

  var west = southWest * (1.0 - latitudeWeight) + northWest * latitudeWeight;
  var east = southEast * (1.0 - latitudeWeight) + northEast * latitudeWeight;
  return west * (1.0 - longitudeWeight) + east * longitudeWeight;
}
